// pixel-ribbon. Generated by scripts/build-esm.mjs from the DEFAULTS of the engine.

export interface PixelRibbonSettings {
  /** Colour of the pixels. Default: '#ffab1a'. */
  color?: string;
  /** 0 to 1. Opacity of the ribbon. Default: 1. */
  opacity?: number;
  /** px, keep px. Side of one pixel. Default: 6. */
  cell?: number;
  /** any CSS unit. Radius of the ribbon at its head. Default: 'clamp(9px, 0.82vw, 14px)'. */
  size?: string;
  /** s. Time the ribbon takes to deflate at rest. Default: 0.75. */
  life?: number;
  /** times size. Reach of the drops a tap throws. Default: 2.2. */
  burst?: number;
}

export interface Instance {
  destroy(): void;
  [key: string]: unknown;
}

export interface Library {
  mount(element: Element, settings?: PixelRibbonSettings): Instance | null;
  destroy(element: Element): void;
  auto(root?: ParentNode): void;
  defaults: Required<PixelRibbonSettings> | null;
  [key: string]: unknown;
}

/** Runs the engine once and returns window.PixelRibbon, or null on a server. */
export function load(): Library | null;
/** Mounts the effect on one element. Does nothing, and returns null, on a server. */
export function mount(element: Element | null, settings?: PixelRibbonSettings): Instance | null;
export function destroy(element: Element | null): void;
/** Mounts every marked element inside root, the document by default. */
export function auto(root?: ParentNode): void;
export function freeze(element: Element | null): void;
export function unfreeze(element: Element | null): void;
